using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.Controls;
public struct TrainingMenuFrame {public bool option,confirm,cancel,cancelFromPad;public Vector2 direction;}
public sealed class TrainingMenuInput:IDisposable {
 sealed class Mods{public bool one,two,seen1,seen2;}sealed class State{public bool held,pressed,previous,at1,at2;public bool pad;}sealed class Watch{public string name;public int modifier;public Dictionary<int,State> states=new Dictionary<int,State>();}
 InputActionMap map;TrainingMenuFrame pending,current;int last=-1;Vector2 previous;bool neutral=true;readonly Dictionary<int,Mods> mods=new Dictionary<int,Mods>();readonly List<Watch> watches=new List<Watch>();Mods Get(int id){if(!mods.TryGetValue(id,out var m)){m=new Mods();mods[id]=m;}return m;}
 public TrainingMenuInput(){var p=KeyConfigService.Ensure();map=new InputActionMap("Menu");for(int i=1;i<=2;i++){int n=i;var r=p.Row("trigger.T"+i);var a=map.AddAction("Trigger"+i,InputActionType.PassThrough);foreach(string b in new[]{r.keyboard,r.pad})if(!string.IsNullOrEmpty(b))a.AddBinding(b);a.performed+=c=>{var m=Get(c.control.device.deviceId);bool held=c.ReadValue<float>()>.5f;if(n==1){m.one=held;m.seen1|=held;}else{m.two=held;m.seen2|=held;}};}
  foreach(var id in new[]{"common.Options","menu.Confirm","menu.Cancel"}){var row=p.Row(id);foreach(var value in new[]{row.keyboard,row.pad}){if(string.IsNullOrEmpty(value))continue;var w=new Watch{name=id,modifier=KeyConfigProfile.Modifier(value)};watches.Add(w);var a=map.AddAction(id+"."+watches.Count,InputActionType.PassThrough,KeyConfigProfile.PathPart(value));a.performed+=c=>{int device=c.control.device.deviceId;if(!w.states.TryGetValue(device,out var state)){state=new State();w.states[device]=state;}var m=Get(device);bool held=c.ReadValue<float>()>.5f;if(held&&!state.held){state.pressed=true;state.at1|=m.one;state.at2|=m.two;}state.held=held;state.pad=!(c.control.device is Keyboard);};}}
  var move=map.AddAction("Navigate",InputActionType.Value);move.AddCompositeBinding("2DVector").With("Up","<Keyboard>/w").With("Down","<Keyboard>/s").With("Left","<Keyboard>/a").With("Right","<Keyboard>/d");move.AddBinding("<Gamepad>/dpad");move.AddBinding("<Gamepad>/leftStick");move.AddBinding("<Joystick>/stick");move.performed+=c=>{var v=c.ReadValue<Vector2>();v=new Vector2(v.x<-.5f?-1:v.x>.5f?1:0,v.y<-.5f?-1:v.y>.5f?1:0);if(v!=previous&&v!=Vector2.zero)pending.direction=v;previous=v;};move.canceled+=c=>previous=Vector2.zero;map.Enable();InputSystem.onDeviceChange+=Changed;
 }
 public TrainingMenuFrame Read()=>Read(Time.frameCount);public TrainingMenuFrame Read(int frame){if(last==frame)return current;last=frame;if(neutral){bool held=false;foreach(var a in map.actions)foreach(var control in a.controls)if(control is ButtonControl b&&b.isPressed)held=true;Drop();if(!held)neutral=false;return current=default;}
  foreach(var w in watches)foreach(var pair in w.states){var s=pair.Value;var m=Get(pair.Key);bool one=m.one||m.seen1||s.at1,two=m.two||m.seen2||s.at2;bool decision=w.modifier==0?!one&&!two:w.modifier==1?one&&!two:two&&!one;bool active=s.held&&(w.modifier==0?!m.one&&!m.two:w.modifier==1?m.one&&!m.two:m.two&&!m.one);bool edge=w.modifier==0?s.pressed&&decision:(s.held||s.pressed)&&decision&&(!s.previous||s.pressed||(w.modifier==1?m.seen1:m.seen2));s.previous=active;if(edge){if(w.name=="common.Options")pending.option=true;else if(w.name=="menu.Confirm")pending.confirm=true;else{pending.cancel=true;pending.cancelFromPad|=s.pad;}}s.pressed=s.at1=s.at2=false;}foreach(var m in mods.Values)m.seen1=m.seen2=false;current=pending;pending=default;return current;
 }
 void Drop(){pending=current=default;previous=Vector2.zero;mods.Clear();foreach(var w in watches)w.states.Clear();}public void Clear(){Drop();last=-1;neutral=true;}
 void Changed(InputDevice d,InputDeviceChange c){if(c==InputDeviceChange.Disconnected||c==InputDeviceChange.Removed||c==InputDeviceChange.Disabled)Clear();}public void Dispose(){InputSystem.onDeviceChange-=Changed;map.Dispose();}
}
